// Glaze Library
// For the license information refer to glaze.hpp
//
// Round-trips sample FIX messages through the dictionary types generated by
// util/fix_codegen/fix_codegen.py (include/glaze/fix/dict/). The sample messages were written
// for this test from the FIX 4.2 / 4.4 message layouts in the FIX Orchestra repository files;
// BodyLength(9) and CheckSum(10) were computed over the '|'-delimited text.

#include <string>
#include <string_view>

#include "glaze/fix/dict/fix42.hpp"
#include "glaze/fix/dict/fix44.hpp"
#include "glaze/fix/fix.hpp"
#include "glaze/json.hpp"
#include "ut/ut.hpp"

using namespace ut;

namespace
{
   constexpr glz::fix_opts pipe_opts{{}, glz::FIX, '|'};

   constexpr std::string_view nos44 =
      "8=FIX.4.4|9=188|35=D|49=SENDER|56=TARGET|34=2|52=20261105-07:00:00.000|11=ORD-1|453=2|448=TRADER1|"
      "447=D|452=11|448=FIRM-A|447=D|452=1|21=1|55=MSFT|54=1|60=20261105-07:00:00.000|38=100|40=2|44=410.25|"
      "59=0|10=097|";
   constexpr std::string_view er44 =
      "8=FIX.4.4|9=164|35=8|49=TARGET|56=SENDER|34=3|52=20261105-07:00:01.000|37=X-77|11=ORD-1|17=E-1|150=F|"
      "39=2|55=MSFT|54=1|38=100|40=2|44=410.25|32=100|31=410.25|151=0|14=100|6=410.25|10=064|";
   constexpr std::string_view md44 =
      "8=FIX.4.4|9=122|35=W|49=SRV|56=CLI|34=5|52=20261105-07:30:00|262=REQ1|55=EUR/USD|268=2|269=0|"
      "270=1.085|271=1500|269=1|270=1.0852|271=2500|10=192|";
   constexpr std::string_view logon44 =
      "8=FIX.4.4|9=63|35=A|49=SRV|56=CLI|34=1|52=20261105-07:30:00|98=0|108=30|141=Y|10=250|";

   // Session layer (FIX 4.4): every message carries the standard header 49/56/34/52.
   constexpr std::string_view heartbeat44 =
      "8=FIX.4.4|9=52|35=0|49=SRV|56=CLI|34=2|52=20261105-07:30:00|112=T1|10=003|";
   constexpr std::string_view test_request44 =
      "8=FIX.4.4|9=52|35=1|49=SRV|56=CLI|34=3|52=20261105-07:30:00|112=T2|10=006|";
   constexpr std::string_view resend_request44 =
      "8=FIX.4.4|9=55|35=2|49=SRV|56=CLI|34=4|52=20261105-07:30:00|7=10|16=0|10=217|";
   constexpr std::string_view reject44 =
      "8=FIX.4.4|9=82|35=3|49=SRV|56=CLI|34=5|52=20261105-07:30:00|45=9|371=44|372=D|373=5|58=bad price|"
      "10=245|";
   constexpr std::string_view sequence_reset44 =
      "8=FIX.4.4|9=57|35=4|49=SRV|56=CLI|34=6|52=20261105-07:30:00|123=Y|36=20|10=106|";
   constexpr std::string_view logout44 =
      "8=FIX.4.4|9=52|35=5|49=SRV|56=CLI|34=7|52=20261105-07:30:00|58=bye|10=161|";
   constexpr std::string_view logon42 =
      "8=FIX.4.2|9=57|35=A|49=SRV|56=CLI|34=1|52=20261105-07:30:00|98=0|108=30|10=083|";

   // Reads `msg` into T, checks the header fields, writes it back and expects the same bytes.
   template <class T>
   T exact(std::string_view msg, int64_t seq)
   {
      T m{};
      auto ec = glz::read<pipe_opts>(m, msg);
      expect(not ec) << ec.custom_error_message;
      expect(m.sender_comp_id == "SRV");
      expect(m.target_comp_id == "CLI");
      expect(m.msg_seq_num == seq);
      expect(m.sending_time == "20261105-07:30:00");
      std::string out;
      expect(not glz::write<pipe_opts>(m, out));
      expect(out == msg) << out;
      return m;
   }
   constexpr std::string_view nos42 =
      "8=FIX.4.2|9=110|35=D|49=SENDER|56=TARGET|34=2|52=20261105-07:00:00|11=ORD-42|21=1|55=IBM|54=2|"
      "60=20261105-07:00:00|38=50|40=1|10=158|";

   template <class T>
   T round_trip(const T& in)
   {
      std::string buf;
      expect(not glz::write<pipe_opts>(in, buf));
      expect(not glz::fix::validate(buf, '|'));
      T out{};
      expect(not glz::read<pipe_opts>(out, buf));
      return out;
   }
}

suite generated_metadata = [] {
   namespace d = glz::fix::fix44;
   "tags"_test = [] {
      static_assert(d::tag::ClOrdID == 11);
      static_assert(d::tag::NoPartyIDs == 453);
      expect(d::begin_string == "FIX.4.4");
   };
   "enum wire values"_test = [] {
      static_assert(char(d::Side::Buy) == '1');
      static_assert(int32_t(d::PartyRole::ExecutingFirm) == 1);
      expect(glz::meta<d::Side>::fix_values[0] == "1");
   };
   "enum names via glaze enum metadata"_test = [] {
      std::string json;
      expect(not glz::write_json(d::OrdType::Limit, json));
      expect(json == R"("Limit")") << json;
      d::OrdType t{};
      expect(not glz::read_json(t, R"("StopLimit")"));
      expect(t == d::OrdType::StopLimit);
   };
   "msg type"_test = [] {
      expect(glz::meta<d::NewOrderSingle>::fix_msg_type == "D");
      expect(glz::meta<d::ExecutionReport>::fix_msg_type == "8");
   };
};

suite fix44_round_trip = [] {
   namespace d = glz::fix::fix44;
   "NewOrderSingle with Parties group"_test = [] {
      d::NewOrderSingle o{};
      auto ec = glz::read<pipe_opts>(o, nos44);
      expect(not ec) << ec.custom_error_message;
      expect(o.cl_ord_id == "ORD-1");
      expect(o.symbol == "MSFT");
      expect(o.side == d::Side::Buy);
      expect(o.ord_type == d::OrdType::Limit);
      expect(o.price == 410.25);
      expect(o.order_qty == 100.0);
      expect(o.time_in_force == d::TimeInForce::Day);
      expect(o.handl_inst == d::HandlInst::AutomatedExecutionNoIntervention);
      expect(o.no_party_ids.size() == 2u);
      if (o.no_party_ids.size() == 2) {
         expect(o.no_party_ids[0].party_id == "TRADER1");
         expect(o.no_party_ids[0].party_role == d::PartyRole{11});
         expect(o.no_party_ids[1].party_id_source == d::PartyIDSource::Proprietary);
         expect(o.no_party_ids[1].party_role == d::PartyRole::ExecutingFirm);
      }
      expect(round_trip(o) == o);
   };
   "ExecutionReport"_test = [] {
      d::ExecutionReport r{};
      auto ec = glz::read<pipe_opts>(r, er44);
      expect(not ec) << ec.custom_error_message;
      expect(r.order_id == "X-77");
      expect(r.exec_type == d::ExecType::Trade);
      expect(r.ord_status == d::OrdStatus::Filled);
      expect(r.cum_qty == 100.0);
      expect(r.leaves_qty == 0.0);
      expect(r.last_px == 410.25);
      expect(round_trip(r) == r);
   };
   "MarketDataSnapshotFullRefresh byte-exact"_test = [] {
      d::MarketDataSnapshotFullRefresh m{};
      auto ec = glz::read<pipe_opts>(m, md44);
      expect(not ec) << ec.custom_error_message;
      expect(m.no_md_entries.size() == 2u);
      if (m.no_md_entries.size() == 2) {
         expect(m.no_md_entries[0].md_entry_type == d::MDEntryType::Bid);
         expect(m.no_md_entries[1].md_entry_px == 1.0852);
         expect(m.no_md_entries[1].md_entry_size == 2500.0);
      }
      std::string out;
      expect(not glz::write<pipe_opts>(m, out));
      expect(out == md44) << out;
   };
   "Logon byte-exact"_test = [] {
      d::Logon l{};
      expect(not glz::read<pipe_opts>(l, logon44));
      expect(l.encrypt_method == d::EncryptMethod::None);
      expect(l.heart_bt_int == 30);
      expect(l.reset_seq_num_flag == true); // Boolean code set -> bool
      std::string out;
      expect(not glz::write<pipe_opts>(l, out));
      expect(out == logon44) << out;
   };
   "built from scratch"_test = [] {
      d::NewOrderSingle o{};
      o.cl_ord_id = "NEW-9";
      o.side = d::Side::SellShort;
      o.transact_time = "20261105-07:30:00";
      o.ord_type = d::OrdType::Market;
      o.symbol = "AAPL";
      o.order_qty = 25;
      o.no_party_ids.push_back({.party_id = "P1", .party_id_source = d::PartyIDSource::Proprietary,
                                .party_role = d::PartyRole::ClientID});
      expect(round_trip(o) == o);
   };
};

suite session_layer = [] {
   namespace d = glz::fix::fix44;
   "Logon"_test = [] {
      auto m = exact<d::Logon>(logon44, 1);
      expect(m.heart_bt_int == 30);
   };
   "Heartbeat"_test = [] { expect(exact<d::Heartbeat>(heartbeat44, 2).test_req_id == "T1"); };
   "TestRequest"_test = [] { expect(exact<d::TestRequest>(test_request44, 3).test_req_id == "T2"); };
   "ResendRequest"_test = [] {
      auto m = exact<d::ResendRequest>(resend_request44, 4);
      expect(m.begin_seq_no == 10);
      expect(m.end_seq_no == 0); // 0 = infinity
   };
   "Reject"_test = [] {
      auto m = exact<d::Reject>(reject44, 5);
      expect(m.ref_seq_num == 9);
      expect(m.ref_tag_id == 44);
      expect(m.ref_msg_type == "D");
      expect(m.session_reject_reason == d::SessionRejectReason::ValueIsIncorrect);
      expect(m.text == "bad price");
   };
   "SequenceReset"_test = [] {
      auto m = exact<d::SequenceReset>(sequence_reset44, 6);
      expect(m.gap_fill_flag == true);
      expect(m.new_seq_no == 20);
   };
   "Logout"_test = [] { expect(exact<d::Logout>(logout44, 7).text == "bye"); };
   "Heartbeat built from scratch"_test = [] {
      d::Heartbeat hb{};
      hb.sender_comp_id = "SRV";
      hb.target_comp_id = "CLI";
      hb.msg_seq_num = 2;
      hb.sending_time = "20261105-07:30:00";
      hb.test_req_id = "T1";
      std::string out;
      expect(not glz::write<pipe_opts>(hb, out));
      expect(out == heartbeat44) << out;
   };
   "PossDupFlag in the header"_test = [] {
      d::Heartbeat hb{};
      hb.sender_comp_id = "SRV";
      hb.target_comp_id = "CLI";
      hb.msg_seq_num = 2;
      hb.poss_dup_flag = true;
      hb.sending_time = "20261105-07:30:00";
      hb.orig_sending_time = "20261105-07:29:00";
      expect(round_trip(hb) == hb);
   };
   "FIX 4.2 Logon"_test = [] {
      auto m = exact<glz::fix::fix42::Logon>(logon42, 1);
      expect(m.encrypt_method == glz::fix::fix42::EncryptMethod::None);
   };
};

suite fix42_round_trip = [] {
   namespace d = glz::fix::fix42;
   "NewOrderSingle 4.2"_test = [] {
      d::NewOrderSingle o{};
      auto ec = glz::read<pipe_opts>(o, nos42);
      expect(not ec) << ec.custom_error_message;
      expect(o.cl_ord_id == "ORD-42");
      expect(o.symbol == "IBM");
      expect(o.side == d::Side::Sell);
      expect(o.ord_type == d::OrdType::Market);
      expect(round_trip(o) == o);
      std::string out;
      expect(not glz::write<pipe_opts>(o, out));
      expect(out.starts_with("8=FIX.4.2|"));
   };
};

suite errors = [] {
   namespace d = glz::fix::fix44;
   "bad checksum rejected"_test = [] {
      std::string bad{logon44};
      bad[bad.size() - 2] = '9';
      d::Logon l{};
      expect(bool(glz::read<pipe_opts>(l, bad)));
   };
   "wrong msg type rejected"_test = [] {
      d::NewOrderSingle o{};
      expect(bool(glz::read<pipe_opts>(o, logon44)));
   };
   "framing a stream"_test = [] {
      std::string stream{logon44};
      stream += md44;
      expect(glz::fix::frame(stream, '|') == logon44.size());
      expect(glz::fix::frame(stream.substr(0, 10), '|') == 0u);
   };
};

int main() { return 0; }
